import numpy as np


def curve(scores, bonus):
    a = np.asarray(scores, dtype=float)
    valid = a[(a >= 0) & (a <= 10)]
    return np.clip(valid + bonus, 0, 10)


def grade_labels(scores, cutoff):
    a = np.asarray(scores)
    return np.where(a >= cutoff, "pass", "fail")


print(curve([3, 5, 8, 12], 0.5))
print(grade_labels([4, 6, 9], 5))

